def parse_kv_pairs(s):
    if s == '':
        return {}
    result = {}
    for part in s.split(';'):
        k, v = part.split('=', 1)
        result[k] = v
    return result

def compare_semver(v1, v2):
    t1 = tuple(int(x) for x in v1.split('.'))
    t2 = tuple(int(x) for x in v2.split('.'))
    if t1 < t2:
        return -1
    if t1 > t2:
        return 1
    return 0

def increment_semver(version, part):
    major, minor, patch = (int(x) for x in version.split('.'))
    if part == 'major':
        major += 1; minor = 0; patch = 0
    elif part == 'minor':
        minor += 1; patch = 0
    elif part == 'patch':
        patch += 1
    return f'{major}.{minor}.{patch}'

import re
def extract_numbers(text):
    return [int(x) for x in re.findall(r'-?\d+', text)]

def parse_query_string(qs):
    if qs == '':
        return {}
    result = {}
    for part in qs.split('&'):
        if '=' in part:
            k, v = part.split('=', 1)
        else:
            k, v = part, ''
        result[k] = v
    return result

def parse_name_email(s):
    start = s.index('<')
    end = s.index('>')
    name = s[:start].strip()
    email = s[start+1:end]
    return (name, email)

def parse_dimensions(s):
    w, h = s.split('x')
    return (int(w), int(h))

def parse_coordinates(s):
    lat, lon = s.split(',')
    return (float(lat), float(lon))

def parse_range(s):
    a, b = s.split('-')
    a, b = int(a), int(b)
    return list(range(a, b + 1))

def parse_fraction(s):
    num, den = s.split('/')
    return int(num) / int(den)

def parse_hex_color(s):
    s = s.lstrip('#')
    r = int(s[0:2], 16)
    g = int(s[2:4], 16)
    b = int(s[4:6], 16)
    return (r, g, b)

def parse_iso_date(s):
    y, m, d = s.split('-')
    return (int(y), int(m), int(d))

def parse_ipv4(s):
    parts = s.split('.')
    return tuple(int(p) for p in parts)

def parse_ini_line(line):
    k, v = line.split('=', 1)
    return (k.strip(), v.strip())

def dedupe_csv_list(s):
    seen = set()
    result = []
    for item in s.split(','):
        item = item.strip()
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def parse_header_line(line):
    k, v = line.split(': ', 1)
    return (k.lower(), v.strip())
